// ---------------------------------------------------------------------------
// Tag / label transformation
// ---------------------------------------------------------------------------

/**
 * Transforms AWS tags to the target provider's tag/label format.
 * - Azure: tags pass through unchanged.
 * - GCP: label keys must be lowercase [a-z0-9_-] only.
 */
export function transformTags(
  provider: CloudProvider,
  tags: Record<string, string>,
): Record<string, string> {
  if (provider === 'azure') {
    // Azure accepts any key unchanged
    return { ...tags };
  }

  // GCP labels: lowercase, only [a-z0-9_-]
  const result: Record<string, string> = {};
  for (const key of Object.keys(tags).sort()) {
    const gcpKey = key
      .toLowerCase()
      .replace(/[^a-z0-9_-]/g, '_');
    result[gcpKey] = tags[key]!;
  }
  return result;
}

// ---------------------------------------------------------------------------
// Region transformation
// ---------------------------------------------------------------------------

/**
 * Transforms an AWS region string to the target provider equivalent.
 * Falls back to the original string with a normalized suffix if not found.
 */
export function transformRegion(
  provider: CloudProvider,
  region: string,
): string {
  const entry = REGION_MAP.get(region);
  if (entry) {
    return provider === 'azure' ? entry.azure : entry.gcp;
  }
  // Unknown region — return as-is
  return region;
}

// ---------------------------------------------------------------------------
// Finding helpers
// ---------------------------------------------------------------------------

/**
 * Creates a TranslationFinding with the given parameters.
 */
export function createFinding(
  resourceId: string,
  severity: FindingSeverity,
  code: string,
  message: string,
  detail?: string,
): TranslationFinding {
  const finding: TranslationFinding = { resourceId, severity, code, message };
  if (detail !== undefined) {
    return { ...finding, detail };
  }
  return finding;
}

/**
 * Returns info-level findings for every attribute key in `source` that is
 * NOT in `mappedKeys`. Keys are processed in sorted order for determinism.
 */
export function collectUnmappedAttrs(
  resourceId: string,
  source: Record<string, unknown>,
  mappedKeys: readonly string[],
): TranslationFinding[] {
  const mapped = new Set(mappedKeys);
  const findings: TranslationFinding[] = [];

  for (const key of Object.keys(source).sort()) {
    if (!mapped.has(key)) {
      findings.push(
        createFinding(
          resourceId,
          'info',
          'UNMAPPED_ATTRIBUTE',
          `Attribute '${key}' was not mapped to the target provider`,
        ),
      );
    }
  }

  return findings;
}

