/**
 * Builds a TraceabilityRecord from the translation context.
 */
export function makeTraceability(
  ctx: TranslationContext,
  engineUsed: string,
  mappingType: MappingType = 'direct',
): TraceabilityRecord {
  return {
    sourceId: ctx.resource.id,
    sourceType: ctx.resource.sourceType,
    registryEntryId: ctx.registryEntry.registry_entry_id,
    mappingType,
    confidence: ctx.registryEntry.confidence,
    engineUsed,
  };
}

// ---------------------------------------------------------------------------
// Gap severity helpers
// ---------------------------------------------------------------------------

/**
 * Maps a registry GapSeverity to a FindingSeverity for translation findings.
 * - blocker -> blocker
 * - major -> warning
 * - minor | informational -> info
 */
export function gapSeverityToFinding(gs: GapSeverity): FindingSeverity {
  switch (gs) {
    case 'blocker':
      return 'blocker';
    case 'major':
      return 'warning';
    case 'minor':
    case 'informational':
      return 'info';
  }
}

/**
 * Computes translation confidence from registry confidence, penalising for
 * unmapped attributes.
 */
export function computeConfidence(
  registryConfidence: number,
  attrs: Record<string, unknown>,
  mappedKeys: readonly string[],
): number {
  const totalKeys = Object.keys(attrs).length;
  if (totalKeys === 0) return registryConfidence;
  const mappedSet = new Set(mappedKeys);
  const mappedCount = Object.keys(attrs).filter((k) => mappedSet.has(k)).length;
  const coverage = mappedCount / totalKeys;
  const raw = registryConfidence * coverage;
  return Math.round(Math.min(1, Math.max(0, raw)) * 100) / 100;
}

/**
 * Emits translation findings for every behavioural gap listed in the
 * registry entry that affects the target provider.
 */
export function emitBehavioralGapFindings(
  ctx: TranslationContext,
): TranslationFinding[] {
  const gaps: BehavioralGap[] = ctx.registryEntry.behavioral_gaps ?? [];
  const findings: TranslationFinding[] = [];

  for (const gap of gaps) {
    if (!gap.affected_targets.includes(ctx.targetProvider)) continue;
    findings.push(
      createFinding(
        ctx.resource.id,
        gapSeverityToFinding(gap.severity),
        gap.gap_id,
        gap.description,
        gap.workaround ?? undefined,
      ),
    );
  }

  return findings;
}

/**
 * Finds a sibling VPC resource in the IR by following relationships from
 * the current resource, or by scanning siblings for `aws_vpc`.
 */
export function findSiblingVpc(
  ctx: TranslationContext,
): { sourceName: string; id: string } | undefined {
  // Check relationships first (e.g. subnet -> vpc_id edge)
  for (const rel of ctx.relationships) {
    if (rel.from === ctx.resource.id || rel.to === ctx.resource.id) {
      const otherId = rel.from === ctx.resource.id ? rel.to : rel.from;
      const sibling = ctx.siblingResources.find((r) => r.id === otherId);
      if (sibling && sibling.sourceType === 'aws_vpc') {
        return { sourceName: sibling.sourceName, id: sibling.id };
      }
    }
  }

  // Fallback: look at vpc_id attribute and match against siblings
  const vpcId = (ctx.resource.attributes as Record<string, unknown>)['vpc_id'];
  if (typeof vpcId === 'string') {
    const sibling = ctx.siblingResources.find(
      (r) => r.sourceType === 'aws_vpc' && (r.id === vpcId || r.sourceName === vpcId),
    );
    if (sibling) {
      return { sourceName: sibling.sourceName, id: sibling.id };
    }
  }

  // Last resort: first VPC sibling
  const first = ctx.siblingResources.find((r) => r.sourceType === 'aws_vpc');
  return first ? { sourceName: first.sourceName, id: first.id } : undefined;
}

/**
 * Finds a sibling resource in the IR by source type, following relationships
 * from the current resource first, then falling back to a type scan.
 */
export function findSiblingByType(
  ctx: TranslationContext,
  sourceType: string,
): { sourceName: string; id: string } | undefined {
  // 1. Check relationships
  for (const rel of ctx.relationships) {
    const otherId =
      rel.from === ctx.resource.id
        ? rel.to
        : rel.to === ctx.resource.id
          ? rel.from
          : null;
    if (!otherId) continue;
    const sibling = ctx.siblingResources.find(
      (r) => r.id === otherId && r.sourceType === sourceType,
    );
    if (sibling) return { sourceName: sibling.sourceName, id: sibling.id };
  }
  // 2. Fallback: scan siblings by type
  const match = ctx.siblingResources.find((r) => r.sourceType === sourceType);
  return match ? { sourceName: match.sourceName, id: match.id } : undefined;
}

/**
 * Extracts the AWS region from an availability zone string.
 * e.g. "us-east-1a" -> "us-east-1"
 */
export function azToRegion(az: string): string {
  // AZs end with a single letter suffix (a-z)
  const match = /^(.+)-[a-z]$/.exec(az);
  return match ? match[1]! : az;
}

